{
  "promptVersion": "pairwise-judge-v1",
  "instruction": "Compare two assistant conversations for the same user scenario. Judge only user-facing quality against the task facts and criteria. Return only structured JSON.",
  "outputSchema": {
    "schemaVersion": "pairwise-judge-output-v1",
    "promptVersion": "pairwise-judge-v1",
    "verdict": "B",
    "criteria": [
      {
        "criterion": "correctness",
        "preference": "B",
        "reason": "Candidate B's mathematical estimation is more accurate for the assumed thickness (2.5 to 3 inches on 300 sq ft yields ~1.8 to 2.1 cubic meters). Candidate A's estimate of 2.5 to 3 cubic meters is too high for a 3-inch thickness (which is 2.12 m³)."
      },
      {
        "criterion": "grounding",
        "preference": "B",
        "reason": "Candidate B explicitly distinguishes floor area from wall area (\"rather than just the floor area\") and correctly identifies that net wall area and wall thickness are required for an exact volume calculation."
      },
      {
        "criterion": "truthfulness",
        "preference": "tie",
        "reason": "Both candidates are truthful and do not make false claims about e-commerce or ordering."
      },
      {
        "criterion": "usefulness",
        "preference": "B",
        "reason": "Candidate B is more useful because it explains the difference between floor area and wall area, and asks the user for the exact parameters (net wall area and thickness) needed to calculate the precise volume."
      },
      {
        "criterion": "conversational_coherence",
        "preference": "tie",
        "reason": "Both candidates maintain a coherent conversation and end with exactly one useful follow-up question."
      }
    ],
    "reason": "Candidate B is superior because it explicitly distinguishes floor area from wall area, provides more accurate mathematical estimates based on its stated assumptions, and asks a highly relevant follow-up question to obtain the exact wall area and thickness required for a precise calculation."
}
